# -*- coding: utf-8 -*-
"""告警语音 - 按状态分类，不区分设备（WAV格式）"""
import base64, os, tempfile

ALERT_SOUNDS = {
    "over_limit": {
        "data": "",
        "ext": ".wav",
    },
    "no_data": {
        "data": "",
        "ext": ".wav",
    },
    "offline": {
        "data": "",
        "ext": ".wav",
    },
}

def get_alert_sound(alert_state):
    """根据告警状态获取语音文件路径。alert_state: over_limit / no_data / offline"""
    info = ALERT_SOUNDS.get(alert_state)
    if not info:
        return None
    ext = info["ext"]
    data = base64.b64decode(info["data"])
    fd, path = tempfile.mkstemp(suffix=ext, prefix="alert_")
    os.write(fd, data)
    os.close(fd)
    return path